theorem constructionPartial_reconstruct {ι : Type} (f : PartialBool ι) :
    constructionPartial {x | promised f x}
      (fun x => Classical.choose x.property) = f

theorem construction_promised_iff {ι : Type}
    (D : Set (BitInput ι)) (f : D → Bool) (x : BitInput ι) :
    promised (constructionPartial D f) x ↔ x ∈ D

theorem construction_exponent_set_wellDefined :
    ({α : ℝ | UniversalPower α}).Nonempty ∧
      BddBelow {α : ℝ | UniversalPower α}

theorem construction_eq8_of_winsAt
    {x : BitInput (BitLoc ℓ r C.size κ)} {i : Column ℓ} {s : Address r}
    (hw : WinsAt f C ℓ r x i s) : constructionOutwardPointers x i s

theorem quantumList_coupling (ha : UnitValued a) (hv : ∀ c, 0 ≤ v c ∧ v c ≤ 1)
    (hf : ∀ L, 0 ≤ f L ∧ f L ≤ 1) (hz : ∀ L, total (weight a L) = 0 → f L = 1) {s : Col}
    {ε : ℝ} (hε0 : 0 ≤ ε) (hε1 : ε ≤ 1) (hd : Dominant a ε s) (hvs : v s = 1) {T₀ : ℕ}
    (hT : (T₀ : ℝ) * ε < 1 / 2) (hfail : ∀ L : List Col, L.length ≤ T₀ → s ∉ L → f L ≤ ε)
    (T : ℕ) (L : List Col) (hL : L.length + T ≤ T₀) :
    1 - missFrom a s T L - T * ε ≤ tval a v f T L

theorem quantum_controlled_reads {ι Γ : Type} [Fintype Γ] {Z : Γ → Type}
    [∀ c, Fintype (Z c)] {n : ℕ}
    {F : ∀ c, BitInput ι → Reg (Z c) ≃ₗᵢ[ℂ] Reg (Z c)}
    (hF : ∀ c, IsCirc n (F c)) :
    IsCirc n (fun x => sigmaOp (fun c => F c x))

theorem quantum_inverse_reads {ι Z : Type} [Fintype Z] {n : ℕ}
    {F : BitInput ι → Reg Z ≃ₗᵢ[ℂ] Reg Z} (hF : IsCirc n F) :
    IsCirc n (fun x => (F x).symm)

theorem quantumVerify_list {cV : ℕ}
    {v : BitInput (Loc k t C) → Col t → ℝ}
    (hv : ∀ c, Runs cV fun x b => bern (v x c) b) (L : List (Col t)) :
    Runs (L.length * cV) fun x b => bern (vall (v x) L) b
